\section{Introduction}

\subsection{Factor-locality}
Let $N=pq$ with $p\le q$ prime. The classical small-factor algorithms --- trial division,
Pollard's rho, Pollard's $p-1$, Fermat's difference of squares, and the elliptic curve
method (ECM) --- all have expected cost controlled by a function of $p$ alone, or of $p$
together with a mild functional of $q$, rather than of $N$. This contrasts with the
index-calculus family, whose cost is a function of $N$.

Factor-locality invites a simple empirical programme: fix an algorithm, sample semiprimes
with a prescribed joint law on $(p,q)$, record the cost $T$, and regress $\log T$ on
$\log p$. The slope $\alpha$ and intercept $\log c$ are the algorithm's coordinates in the
\emph{factor-local exponent plane}.

Two design features matter. An \emph{arm} is the conditional law of $q$ given $p$: e.g.\
$q=\mathrm{nextprime}(p)$; $q\in[2p,4p]$ (\emph{bounded-ratio}); $q$ uniform in a fixed
range. A cost law deserves the name only if its exponent is stable across arms.
Exponents were fitted per arm and pooled with bootstrap confidence intervals at
$n=6000$ semiprimes per arm.

\subsection{The measurement}
The pooled fits were
\[
\alpha_{\mathrm{td}} = 1.0009\ [1.000,1.002],\qquad
\alpha_{\rho} = 0.4994\ [0.485,0.510],\qquad
\alpha_{\mathrm F} = 0.9932 .
\]
Arm-invariance held to first order for trial division and rho and failed strongly for
Fermat, as predicted before the data were taken. ECM produced no stable exponent: across
the accessible range the fit ranged over $[-0.86,+0.04]$. Two earlier runs of this
experiment contained implementation defects and are superseded by the present one; they
are disclosed here for completeness. The ECM cost denominator was validated before data
collection.

\subsection{Contributions}
\begin{enumerate}
\item Three exact laws (\S\S\ref{sec:td}--\ref{sec:fermat}) that the three stable fits are
      measuring, proved unconditionally.
\item A rigidity theorem (\S\ref{sec:rigidity}): the exponents $(1,1,\tfrac12)$ are forced
      by the brackets alone; plus an exact closed form for the finite-$p$ Fermat fit that
      explains the measured $0.9932$ quantitatively.
\item The ECM self-destruction wall (\S\ref{sec:wall}): beyond a computable bound the
      success event is \emph{empty}, so no single $(\alpha,c)$ exists for ECM.
\item The exact wall threshold (\S\ref{sec:threshold}): $B^{*}(p)=\max_{n\in \Wwin(p)}\mpp(n)$,
      a least-element characterisation, and the demonstration that prime \emph{powers} set
      the wall.
\item The validity edge and the joint nature of degeneration (\S\ref{sec:edge}).
\item Refutation of the proxy hypothesis and exact firing-rate combinatorics
      (\S\S\ref{sec:proxy}--\ref{sec:rates}).
\end{enumerate}

\section{Notation}

Throughout, $N=pq$ with $p\le q$ prime, $\minFac(N)$ is the least prime factor,
$\lpf(n)$ the largest prime factor, $\omega(n)$ the number of distinct prime factors,
$\pi(B)$ the prime counting function, and $v_r(n)$ the exponent of the prime $r$ in $n$.

\begin{definition}[Largest prime power; powersmoothness; stage-one scalar]
For $n\ge 2$ set $\mpp(n)=\max_{r\mid n,\ r\ \text{prime}} r^{v_r(n)}$, and $\mpp(n)=0$ for
$n\le 1$. An integer $n$ is \emph{$B$-powersmooth} if $r^{v_r(n)}\le B$ for every prime
$r\mid n$, equivalently $\mpp(n)\le B$. The \emph{stage-one scalar} is
$k(B)=\operatorname{lcm}(1,2,\dots,B)$. For $n,B\ge 1$ one has $n\mid k(B)$ if and only if
$n$ is $B$-powersmooth.
\end{definition}

\begin{definition}[Hasse window]
$\Wwin(p)=\{\,n\in\mathbb Z:\ |n-(p+1)|\le 2\sqrt p\,\}$, of width $4\sqrt p$; by Hasse's
theorem $\#E(\Fp)\in \Wwin(p)$ for every elliptic curve $E/\Fp$. In computations we use
the integer enclosure $[\,p+1-2(\lfloor\sqrt p\rfloor+1),\ p+1+2(\lfloor\sqrt p\rfloor+1)\,]$,
which provably contains every Hasse-admissible integer; $\Wtop(p)$ denotes its top.
\end{definition}

A \emph{fitted exponent} at a single point is $\log_p(\text{cost})$; asymptotically it is
the limit of these along an arm.

\section{Trial division: $\alpha=1$ exactly}\label{sec:td}

Trial division examines candidate divisors in increasing order; the largest divisor
examined before $N$ splits is $\minFac(N)$. Set $\tdCost(N)=\minFac(N)$.

\begin{theorem}[Exact semiprime cost]\label{thm:tdcost}
If $p,q$ are prime with $p\le q$ then $\tdCost(pq)=p$.
\end{theorem}

\begin{proof}[Proof sketch]
$p\mid pq$ gives $\minFac(pq)\le p$. Conversely $\minFac(pq)$ is a prime dividing $pq$,
hence equals $p$ or $q$ by Euclid's lemma, and $p\le q$.
\end{proof}

\begin{theorem}[Exact arm invariance]
For primes $p\le q$ and $p\le q'$ one has $\tdCost(pq)=\tdCost(pq')$.
\end{theorem}

\begin{corollary}\label{cor:tdexp}
For primes $p\le q$ with $p>1$, $\log_p \tdCost(pq)=1$.
\end{corollary}

The exponent is thus pointwise, not asymptotic, so the confidence interval should abut $1$
from above --- as $[1.000,1.002]$ does; the invariance is exact, the residual first-order
dependence being harness overhead; and there is no fitted constant, $c=1$.

\section{Pollard rho: a two-sided birthday bracket}\label{sec:rho}

Model the residues visited by the rho iteration modulo $p$ as $t$ independent uniform draws
from a set of size $m$. The \emph{no-collision ratio} is
\[
R(m,t)=\frac{m^{\underline{t}}}{m^{t}}=\prod_{i=0}^{t-1}\Bigl(1-\frac im\Bigr),\qquad t\le m .
\]

\begin{lemma}[Weierstrass product inequality]\label{lem:weier}
If $0\le x_i\le 1$ for $i<t$ then $\prod_{i<t}(1-x_i)\ \ge\ 1-\sum_{i<t}x_i$.
\end{lemma}

\begin{proof}[Proof sketch]
Induction on $t$; the step reduces to $(1-S)(1-x)\ge 1-S-x$, i.e.\ $Sx\ge 0$.
\end{proof}

\begin{theorem}[Two-sided birthday bracket]\label{thm:bracket}
For $0<m$ and $t\le m$,
\[
1-\frac{t(t-1)}{2m}\ \le\ R(m,t)\ \le\ \exp\!\Bigl(-\frac{t(t-1)}{2m}\Bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Upper bound: apply $1-x\le e^{-x}$ factorwise and sum $\sum_{i<t} i/m=t(t-1)/2m$.
Lower bound: Lemma~\ref{lem:weier} with $x_i=i/m\in[0,1]$ and the same sum.
\end{proof}

\begin{theorem}[Threshold, two-sided]\label{thm:threshold}
Write $P_{\mathrm{coll}}(m,t)=1-R(m,t)$ and let $t\le m$.
\begin{enumerate}
\item If $t(t-1)\le m$ then $P_{\mathrm{coll}}(m,t)\le \tfrac12$.
\item If $t\ge 1+\sqrt{2m\log 2}$ then $P_{\mathrm{coll}}(m,t)\ge \tfrac12$.
\end{enumerate}
Hence any $T(m)$ at which the collision probability first reaches $\tfrac12$ satisfies
$\sqrt m \le T(m) \le 1+\sqrt{2\log 2}\,\sqrt m$, with $\sqrt{2\log 2}=1.17741\ldots$
\end{theorem}

\begin{proof}[Proof sketch]
(1) The lower bound of Theorem~\ref{thm:bracket} gives $P_{\mathrm{coll}}\le t(t-1)/2m\le\tfrac12$.
(2) The upper bound gives $P_{\mathrm{coll}}\ge 1-e^{-t(t-1)/2m}$, and the hypothesis yields
$t(t-1)\ge 2m\log 2$.
\end{proof}

The corridor $[\sqrt m,\ 1+1.1774\sqrt m]$ is wide in the constant and degenerate in the
exponent; this is what the fitted $0.4994\,[0.485,0.510]$ reports.

\begin{definition}\label{def:bt}
Say $t$ is a \emph{birthday threshold for modulus $m$} if
$\sqrt m \le t \le 2+\sqrt{2m\log 2}$.
\end{definition}

\begin{proposition}[The bracket is inhabited]
For every $m\ge1$ the value $t=\lceil\sqrt{2m\log 2}\rceil+1$ is a birthday threshold for
$m$ and satisfies $t\ge 1+\sqrt{2m\log 2}$; hence (for $t\le m$) it achieves collision
probability at least $\tfrac12$.
\end{proposition}

\section{Fermat's method: the exact $(p+q)/2$ law}\label{sec:fermat}

\begin{theorem}[Exact halting abscissa]\label{thm:fermathalt}
Let $p<q$ be odd primes and $N=pq$. Then $x=\frac{p+q}{2}$, $y=\frac{q-p}{2}$ are integers
with $x^2-y^2=N$, and no $x_0<\frac{p+q}{2}$ admits $x_0^2-y_0^2=N$ with $y_0\ge0$.
\end{theorem}

\begin{proof}[Proof sketch]
Both $p\pm q$ are even and $\bigl(\tfrac{p+q}2\bigr)^2-\bigl(\tfrac{q-p}2\bigr)^2=pq$.
Any representation gives a factorisation $N=(x_0-y_0)(x_0+y_0)$; as $N$ is a semiprime the
only factor pairs are $\{p,q\}$ and $\{1,N\}$, yielding $x_0=(p+q)/2$ or $x_0=(N+1)/2$, and
$(N+1)/2-(p+q)/2=(p-1)(q-1)/2>0$.
\end{proof}

\begin{definition}
The \emph{Fermat gap} is $G(p,q)=\frac{p+q}{2}-\sqrt{pq}$; the number of trial abscissae is
$\frac{p+q}{2}-\lceil\sqrt N\rceil+1$.
\end{definition}

\begin{theorem}[Closed form]
$G(p,q)=\dfrac{(\sqrt q-\sqrt p)^2}{2}$: the Fermat gap is exactly the
arithmetic--geometric mean defect of $\{p,q\}$.
\end{theorem}

\begin{theorem}[Bounded-ratio arm: $\alpha=1$ with pinned constant]\label{thm:gapbracket}
If $0<p$ and $2p\le q$ then $G(p,q)\ge p/12$. If $q\le 4p$ then $G(p,q)\le 5p/2$.
\end{theorem}

\begin{proof}[Proof sketch]
Lower: $G$ is increasing in $q$, and $G(p,2p)=\tfrac{3-2\sqrt2}{2}p=0.08578\ldots p\ge p/12$.
Upper: discard $-\sqrt{pq}$ and use $q\le 4p$.
\end{proof}

\begin{theorem}[Strong arm dependence]
For $0<p\le q<q'$ one has $G(p,q)<G(p,q')$.
\end{theorem}

\begin{theorem}[Uniform arm sensitivity]\label{thm:deriv}
Extend $G$ to real second argument. Then $\partial_x G(p,x)=\tfrac12-\tfrac12\sqrt{p/x}$ for
$p,x>0$, and $x\ge 2p$ implies
$\partial_x G(p,x)\ge \tfrac12\bigl(1-\tfrac1{\sqrt2}\bigr)=0.14644\ldots>0$.
\end{theorem}

\begin{corollary}[Invariance dichotomy, derivative form]
The $q$-derivative of the trial-division cost is identically $0$; the $q$-derivative of the
Fermat cost is bounded below by an absolute positive constant on every arm with $q\ge2p$.
\end{corollary}

\section{Rigidity of the plane $(1,1,\tfrac12)$}\label{sec:rigidity}

\begin{lemma}[Bracket implies exponent]\label{lem:bracket2exp}
Let $P_n\to\infty$ and $aP_n^{\alpha}\le f(n)\le bP_n^{\alpha}$ with $0<a\le b$. Then
$\log_{P_n}f(n)\to\alpha$.
\end{lemma}

\begin{proof}[Proof sketch]
$\log_P f=\alpha+\log(f/P^{\alpha})/\log P$, and the numerator is bounded between $\log a$
and $\log b$ while $\log P\to\infty$.
\end{proof}

\begin{theorem}[Exponent-plane rigidity]\label{thm:rigidity}
Fix primes $P_n\to\infty$ and $Q_n$ with $2P_n\le Q_n\le 4P_n$, and let $T(n)$ be
\emph{any} birthday threshold for $P_n$ in the sense of Definition~\ref{def:bt}. Then
\[
\log_{P_n}\tdCost(P_nQ_n)\to 1,\qquad
\log_{P_n}G(P_n,Q_n)\to 1,\qquad
\log_{P_n}T(n)\to \tfrac12 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
The first quantity is identically $1$ (Corollary~\ref{cor:tdexp}). The second is
Lemma~\ref{lem:bracket2exp} with $a=1/12$, $b=5/2$ (Theorem~\ref{thm:gapbracket}). The
third is Lemma~\ref{lem:bracket2exp} with $\alpha=\tfrac12$ applied to
$\sqrt{P_n}\le T(n)\le (2+\sqrt{2\log2})\sqrt{P_n}$.
\end{proof}

\begin{proposition}[The arm is inhabited]
Every prime $p$ has a prime partner $q$ with $2p\le q\le 4p$ (Bertrand's postulate applied
to $2p$).
\end{proposition}

\subsection{The Fermat fit at finite $p$, exactly}

\begin{theorem}[Exact finite-$p$ Fermat exponent]\label{thm:exactfit}
$G(p,2p)=\bigl(\tfrac32-\sqrt2\bigr)p$, and for $p>1$
\[
\log_p G(p,2p)\;=\;1+\frac{\log\bigl(\tfrac32-\sqrt2\bigr)}{\log p}.
\]
\end{theorem}

\begin{corollary}
Since $0<\tfrac32-\sqrt2=0.08579\ldots<1$, one has $\log_p G(p,2p)<1$ for all $p>1$: the
fitted exponent lies strictly below $1$ at every finite scale, with the sign of the
observed deficit.
\end{corollary}

\begin{theorem}[The scale a fit demands]\label{thm:scale}
If $1-\log_p G(p,2p)\le\varepsilon$ then
$\varepsilon\log p\ \ge\ -\log\bigl(\tfrac32-\sqrt2\bigr)=2.45591\ldots$
\end{theorem}

With the observed deficit $\varepsilon=1-0.9932=0.0068$ this forces $\log p\gtrsim 361$, i.e.
$p\gtrsim e^{361}\approx 10^{157}$. The measured $0.9932$ is therefore the exactly predicted
finite-size correction $|\log c|/\log p$, not evidence against $\alpha_{\mathrm F}=1$.

\section{The ECM self-destruction wall}\label{sec:wall}

\subsection{The stage-one mechanism}
Stage one selects a curve $E$ over $\Zmod{N}$ and a point $P$, and computes $k(B)\cdot P$.
Reduction modulo the two primes gives orders $m_p$ and $m_q$ lying in the corresponding
Hasse windows. Write
\[
\mathrm{Splits}(m_p,m_q,k)\iff (m_p\mid k)\oplus(m_q\mid k),\qquad
\mathrm{Degenerate}(m_p,m_q,k)\iff (m_p\mid k)\wedge(m_q\mid k).
\]
Degeneration implies non-splitting, and $1\le n\le B$ implies $n\mid k(B)$.

\begin{theorem}[Self-destruction wall]\label{thm:wall}
Suppose $\Wtop(p)\le B$ and $\Wtop(q)\le B$. Then for every pair of nonzero orders
$m_p\in \Wwin(p)$, $m_q\in \Wwin(q)$ one has $\mathrm{Degenerate}(m_p,m_q,k(B))$.
\end{theorem}

\begin{corollary}[Empty success event]
Under the hypotheses of Theorem~\ref{thm:wall}, no curve splits; the number of successes in
any finite batch of curves is $0$; and for an infinite stream of curves the split event
never occurs, so the uncapped expected number of curves to a split is $+\infty$.
\end{corollary}

\begin{remark}[Why ECM has no exponent]
A power law $T\approx c\,p^{\alpha}$ asserts a finite cost, whereas behind the wall the
success probability is exactly $0$ and the uncapped cost is infinite. Hence no exponent can
hold uniformly in $B$, and every fitted ECM exponent depends silently on the $B$-schedule:
the observed range $[-0.86,+0.04]$ is the symptom. The honest object is the family
$\{(\alpha,c)(B_1)\}$ restricted to $B_1\lesssim\min(p,q)/2$.
\end{remark}

\section{The exact wall threshold: prime powers, not primes}\label{sec:threshold}

Define $B^{*}(p)=\max_{n\in \Wwin(p)}\mpp(n)$, and call $p$ \emph{totally degenerate at $B$}
if every nonzero $n\in \Wwin(p)$ divides $k(B)$.

\begin{theorem}[Exact threshold]\label{thm:exactwall}
For $B\ge1$: $p$ is totally degenerate at $B$ if and only if $B^{*}(p)\le B$.
\end{theorem}

\begin{proof}[Proof sketch]
$n\mid k(B)$ iff $n$ is $B$-powersmooth iff $\mpp(n)\le B$; a supremum over the finite
window is $\le B$ iff every member is.
\end{proof}

\begin{theorem}[Least element]
For $p\ge1$, $B^{*}(p)$ is the least element of $\{B\ge1: p\ \text{totally degenerate at } B\}$,
and $2\le B^{*}(p)\le \Wtop(p)$.
\end{theorem}

\begin{theorem}[Prime powers set the wall]
If $r$ is prime, $e\ge1$, $r^{e}\in \Wwin(p)$ and $B<r^{e}$, then $p$ is not totally
degenerate at $B$.
\end{theorem}

\begin{example}[The wall at $p=101$]
The window at $p=101$ is $[80,124]$. For every $B<121$ the prime $101$ is \emph{not} totally
degenerate, and it \emph{is} totally degenerate at $B=124$. Hence $B^{*}(101)=121=11^{2}$,
although the largest prime in the window is $113$.
\end{example}

The threshold functional $p\mapsto \max_{n\in \Wwin(p)}\mpp(n)$ is a smooth-number statistic
of an interval of length $4\sqrt p$, not a prime-counting statistic; questions about the
size of $B^{*}(p)$ therefore live in the theory of smooth numbers in short intervals.

\begin{conjecture}\label{conj:half}
$B^{*}(p)\ge p/2$ for every prime $p\ge19$; equivalently, every Hasse window contains an
integer with a prime-power factor exceeding $p/2$.
\end{conjecture}

An unconditional bound $B^{*}(p)\ge cp$ is equivalent to a Legendre-type statement about
prime powers in intervals of length $4\sqrt p$.

\subsection{Firing count and saturation}
Let $F(p,B)=\#\{n\in \Wwin(p): n\mid k(B)\}$.

\begin{theorem}[Firing count is a powersmooth count]\label{thm:fc}
If $B\ge1$ and $0\notin \Wwin(p)$ then $F(p,B)=\#\{n\in \Wwin(p): \mpp(n)\le B\}$.
\end{theorem}

\begin{theorem}[Saturation at the wall]
For $p\ge19$ and $B\ge1$: $F(p,B)=|\Wwin(p)|$ if and only if $B^{*}(p)\le B$; and
$F(p,\cdot)$ is nondecreasing.
\end{theorem}

\section{Joint degeneration and the validity edge}\label{sec:edge}

\begin{theorem}[One-sided crossing splits]\label{thm:onesided}
Suppose $\Wtop(p)\le B$, $m_p\in \Wwin(p)$ is nonzero, and $m_q\nmid k(B)$. Then
$\mathrm{Splits}(m_p,m_q,k(B))$ holds.
\end{theorem}

Crossing the wall at one prime alone is therefore a deterministic success, not a failure;
only simultaneous crossing is fatal, which is why the smaller prime governs the edge.

\begin{lemma}
For $p\ge19$ one has $2+4\lfloor\sqrt p\rfloor<p$.
\end{lemma}

\begin{theorem}[Validity edge]\label{thm:edge}
Let $p\ge19$ and $2B\le p$. Then every $n\in \Wwin(p)$ satisfies $n>B$.
\end{theorem}

\begin{corollary}[Safe zone]
If $p,q\ge19$ and $2B\le\min(p,q)$ then no order in either window is forced to divide $k(B)$
by size alone: the self-destruction mechanism is inoperative. In practice
$B_1\lesssim\min(p,q)/2$ is the validity edge for any fitted ECM cost law.
\end{corollary}

Theorem~\ref{thm:edge} excludes the \emph{size} mechanism only; a large but powersmooth
order may still die, and that is precisely the difference the algorithm exploits inside the
safe zone.

\section{The proxy hypothesis, refuted}\label{sec:proxy}

\begin{theorem}[Coarse proxies are blind to firing]\label{thm:blind}
For every $B\ge2$ put $a=\lfloor\log_2 B\rfloor$, $m=2^{a}$, $m'=2^{a+1}$. Then $m,m'>0$,
$\lpf(m)=\lpf(m')=2$, $\omega(m)=\omega(m')=1$, and yet $m\mid k(B)$ while $m'\nmid k(B)$.
\end{theorem}

\begin{proof}[Proof sketch]
$2^{a}\le B$ gives $m\mid k(B)$. If $m'\mid k(B)$ then $m'$ is $B$-powersmooth, so
$2^{a+1}\le B$, contradicting $B<2^{a+1}$.
\end{proof}

Any predictor built from $(\lpf,\omega)$ is constant on this pair and therefore cannot
separate firing from non-firing; the family is infinite, one instance per $B$. The positive
replacement is Theorem~\ref{thm:fc}: firing is exactly powersmoothness, and aggregate
stage-one behaviour is governed by the distribution of $\mpp$ over the width-$4\sqrt p$
window. The statistic $\lpf$ forgets multiplicity --- exactly what the wall at $p=101$ turns
on --- and $\omega$ forgets size.

\section{Firing rates are counts, not probabilities}\label{sec:rates}

\begin{theorem}[Exact firing rate]
In $\Zmod{m}$ the number of residues $a$ with $m\mid ka$ is exactly $\gcd(m,k)$;
equivalently $a$ fires iff the cofactor $m/\gcd(m,k)$ divides $a$.
\end{theorem}

\begin{theorem}[Multi-curve success count]
For $c$ independent points of $\Zmod{m}$, the number of $c$-tuples on which $k$ fires at
least once is exactly $m^{c}-(m-\gcd(m,k))^{c}$; the success rate is exactly
$1-(1-\rho)^{c}$ with $\rho=\gcd(m,k)/m$. No independence assumption is needed: the tuple
space is a product, and this is a counting identity.
\end{theorem}

\begin{theorem}[Saturation and jumps]
$\gcd(m,k(B))$ is the largest $B$-powersmooth divisor of $m$; in particular
$\gcd(m,k(B))=m$ iff $m$ is $B$-powersmooth. As the prime cutoff advances through the
primes $\le B$, the cumulative firing count changes only when the cutoff passes a prime
$r\mid m$, and then multiplies by $r^{\min(v_r(m),\ \lfloor\log_r B\rfloor)}$.
\end{theorem}

\begin{corollary}[Long flat runs; no dose response]
At most $\omega(m)\le\log_2 m$ of the $\pi(B)$ schedule steps are firing positions, so some
run of at least $\pi(B)/(\omega(m)+1)$ consecutive schedule primes leaves the firing count
exactly unchanged. A measured smooth dose--response curve in the prime cutoff is an
artefact of averaging.
\end{corollary}

\begin{example}[Order completion beats the collision floor]
Take $m=720$ and $B=10$, so $k(10)=2520$ and $\gcd(720,2520)=360$: exactly half of the $720$
points fire. The folklore collision heuristic predicts a rate at most $1.44\,B/m=1/50$; the
observed rate is more than $25$ times larger, so order completion, not collision, is the
mechanism.
\end{example}

\begin{remark}[Rank two]
For $\Zmod{m_1}\times\Zmod{m_2}$ the number of firing points is $\gcd(m_1,k)\gcd(m_2,k)$, so
a rank-two group fires at least as often as a cyclic group of the same order.
\end{remark}

\section{Algorithms}

\textbf{(A) Exact wall locator.} Given $p$, build the integer Hasse window, sieve-factor each
member, compute $\mpp$, and return the maximum. Cost $O(\sqrt p\log\log p)$ after sieving a
window of $\approx 4\sqrt p+5$ members.

\smallskip
\textbf{(B) Powersmoothness / firing oracle.} Decide $m\mid k(B)$ by $\mpp(m)\le B$, and
compute $\gcd(m,k(B))=\prod_{r\mid m}r^{\min(v_r(m),\lfloor\log_r B\rfloor)}$ without
materialising $k(B)$.

\smallskip
\textbf{(C) Pooled log--log exponent fit with bootstrap confidence interval.} Sample $n$
semiprimes per arm, record cost, regress $\log T$ on $\log p$ by ordinary least squares, and
resample pairs $B$ times for a percentile interval on the slope; cost $O(nB)$.

\section{Discussion}

\emph{What survived.} Everything stated as an exact identity: $\minFac(pq)=p$; Fermat's
halting abscissa; the two-sided birthday bracket; the powersmoothness characterisation of
firing; the least-element form of the wall. These are theorems about the algorithms'
definitions, not about random inputs, so they do not degrade when the sampler changes; only
the finite-size correction does, and \S\ref{sec:rigidity} computes it in closed form.

\emph{What failed.} (i) A single $(\alpha,c)$ for ECM, refuted structurally: the success
probability is exactly $0$ behind the wall. (ii) $\lpf$ and $\omega$ as drivers, refuted by
an explicit infinite family. (iii) An unconditional lower bound $B^{*}(p)\ge cp$: not false,
but equivalent to a Legendre-type statement about prime powers in short intervals
(Conjecture~\ref{conj:half}).

\emph{Moral.} The plane is a plane only where the cost functional is finite and arm-stable.
For trial division, rho and Fermat it is, and the exponents are rigid. For ECM the correct
object is a validity region with a computable boundary; reporting a single ECM exponent is a
category error, and a wandering fit is the diagnostic that detects it.

\section{Future directions}

\begin{enumerate}
\item \textbf{Powersmooth-free windows and the true size of $B^{*}(p)$.} The identity
$B^{*}(p)=\max_{n\in \Wwin(p)}\mpp(n)$ converts ECM's failure into a question about the
largest prime power in a short interval --- a smooth-number question rather than a prime-gap
question. Any bound on prime powers in $[p+1-2\sqrt p,\ p+1+2\sqrt p]$ transfers immediately.
\item \textbf{Joint-wall asymmetry.} Theorem~\ref{thm:onesided} suggests deliberately
asymmetric bound schedules that straddle the two walls; quantifying the measure of $B$ for
which exactly one wall is crossed --- a function of $|B^{*}(p)-B^{*}(q)|$ --- would turn the
wall into a resource.
\item \textbf{The distribution of $\mpp$ across the window.} Theorem~\ref{thm:fc} makes
$B\mapsto F(p,B)$ literally the empirical distribution function of $\mpp$ over $\Wwin(p)$; a
Dickman-type law for prime powers in short intervals would give the exact $B$-dependence of
stage-one success, hence the exact family $\{(\alpha,c)(B_1)\}$.
\item \textbf{Beyond cyclic orders.} The rank-two firing formula
$\gcd(m_1,k)\gcd(m_2,k)$ suggests curve-selection strategies with forced torsion; their
consequences in this exact framework are unexplored.
\item \textbf{Extending the plane.} Pollard's $p-1$ and Williams' $p+1$ have the same order
completion structure with the window replaced by a single value, so their walls are exactly
$\mpp(p-1)$ and $\mpp(p+1)$ --- degenerate but instructive special cases of
Theorem~\ref{thm:exactwall}.
\end{enumerate}

\end{document}

