#!/usr/bin/env python3
"""ECM stage-1 wall-crossing simulator: expected curves to a split, as B rises.

Model.  A random curve modulo N = p*q gives a pair of group orders (m_p, m_q), one in
each Hasse window; we take them uniform and independent over the two windows.  Stage 1
splits N exactly when the point dies at exactly one prime, i.e. when exactly one of
m_p, m_q is B-powersmooth:

    P_split(B) = u(B) (1 - v(B)) + v(B) (1 - u(B)),
    u(B) = #{n in W(p) : mpp(n) <= B} / |W(p)|,     v(B) likewise at q.

The expected number of curves to a split is 1 / P_split(B), which is finite in the
working regime, dips to its minimum, and becomes *infinite* the moment B passes both
walls B*(p) and B*(q): behind the wall u = v = 1, so P_split = 0 exactly.  This is the
structural reason no single power law T ~ c p^alpha can describe ECM.

Everything is an exact rational computation over the finite windows -- no sampling.
"""

from __future__ import annotations

import math
from typing import Dict, List, Tuple


def factorize(n: int) -> Dict[int, int]:
    out: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


def max_prime_power(n: int) -> int:
    return 0 if n <= 1 else max(r ** e for r, e in factorize(n).items())


def hasse_window(p: int) -> List[int]:
    s = math.isqrt(p)
    return list(range(max(1, p + 1 - 2 * (s + 1)), p + 1 + 2 * (s + 1) + 1))


def window_profile(p: int) -> List[int]:
    """The multiset of largest prime powers across the Hasse window at p."""
    return [max_prime_power(n) for n in hasse_window(p)]


def death_fraction(profile: List[int], bound: int) -> float:
    return sum(1 for v in profile if v <= bound) / len(profile)


def split_probability(prof_p: List[int], prof_q: List[int], bound: int) -> float:
    u, v = death_fraction(prof_p, bound), death_fraction(prof_q, bound)
    return u * (1 - v) + v * (1 - u)


def expected_curves(prof_p: List[int], prof_q: List[int], bound: int) -> float:
    s = split_probability(prof_p, prof_q, bound)
    return math.inf if s == 0.0 else 1.0 / s


def report(p: int, q: int, bounds: Tuple[int, ...]) -> None:
    prof_p, prof_q = window_profile(p), window_profile(q)
    wall_p, wall_q = max(prof_p), max(prof_q)
    edge = min(p, q) // 2
    print(f"N = {p} * {q} = {p * q}")
    print(f"  wall at p: B*({p}) = {wall_p}    wall at q: B*({q}) = {wall_q}"
          f"    validity edge: B <= {edge}")
    print(f"{'B':>7} {'die at p':>10} {'die at q':>10} {'P(split)':>11} "
          f"{'E[curves]':>12}  regime")
    for b in bounds:
        u, v = death_fraction(prof_p, b), death_fraction(prof_q, b)
        s = split_probability(prof_p, prof_q, b)
        e = expected_curves(prof_p, prof_q, b)
        if u == 1.0 and v == 1.0:
            regime = "BEHIND THE WALL - no curve can ever split"
        elif u == 1.0 or v == 1.0:
            regime = "one-sided crossing - deterministic split"
        elif 2 * b <= min(p, q):
            regime = "inside the validity edge"
        else:
            regime = "working regime"
        print(f"{b:>7} {u:>10.3f} {v:>10.3f} {s:>11.4f} "
              f"{('inf' if e == math.inf else f'{e:.2f}'):>12}  {regime}")
    print()


if __name__ == "__main__":
    report(101, 1009, (10, 25, 50, 80, 110, 121, 130, 300, 700, 1000, 1074))
    report(401, 601, (20, 60, 150, 200, 300, 443, 500, 600, 641, 700))
    print("The divergence is not a large constant: behind the wall the success event is")
    print("empty, so the uncapped expectation is exactly +infinity.  A fitted ECM")
    print("exponent is therefore only meaningful below the validity edge B <= min(p,q)/2.")

