#!/usr/bin/env python3
"""Exact locator of the ECM self-destruction wall B*(p).

B*(p) = max over the Hasse window W(p) = [p+1-2 sqrt p, p+1+2 sqrt p] of mpp(n), the
largest prime power exactly dividing n.  Total degeneration of every window order at
smoothness bound B happens if and only if B >= B*(p), and B*(p) is least with this
property.  The window is factored by a segmented sieve, so the cost is
O(sqrt(p) log log p) after an O(sqrt(p)) base sieve.
"""

from __future__ import annotations

import math
from typing import Dict, List, Tuple


def base_primes(limit: int) -> List[int]:
    """All primes <= limit by a simple sieve of Eratosthenes."""
    flag = bytearray([1]) * (limit + 1)
    flag[0:2] = b"\x00\x00"
    for i in range(2, math.isqrt(limit) + 1):
        if flag[i]:
            flag[i * i:limit + 1:i] = bytearray(len(range(i * i, limit + 1, i)))
    return [i for i in range(2, limit + 1) if flag[i]]


def hasse_window_bounds(p: int) -> Tuple[int, int]:
    """Integer enclosure [lo, hi] of the Hasse interval around p+1."""
    s = math.isqrt(p)
    return max(1, p + 1 - 2 * (s + 1)), p + 1 + 2 * (s + 1)


def segmented_max_prime_power(lo: int, hi: int) -> Dict[int, int]:
    """mpp(n) for every n in [lo, hi], by a segmented sieve of prime powers."""
    size = hi - lo + 1
    rest = list(range(lo, hi + 1))          # unfactored part of each n
    mpp = [1] * size                        # running largest prime power
    for r in base_primes(math.isqrt(hi) + 1):
        start = ((lo + r - 1) // r) * r
        for n in range(start, hi + 1, r):
            i = n - lo
            pw = 1
            while rest[i] % r == 0:
                rest[i] //= r
                pw *= r
            if pw > mpp[i]:
                mpp[i] = pw
    for i in range(size):
        if rest[i] > 1 and rest[i] > mpp[i]:  # a single large prime survives
            mpp[i] = rest[i]
    return {lo + i: mpp[i] for i in range(size)}


def wall(p: int) -> int:
    """B*(p): the exact smoothness bound at which the whole Hasse window degenerates."""
    lo, hi = hasse_window_bounds(p)
    return max(segmented_max_prime_power(lo, hi).values())


def wall_witness(p: int) -> Tuple[int, int]:
    """(B*(p), a window integer whose largest prime power attains it)."""
    lo, hi = hasse_window_bounds(p)
    table = segmented_max_prime_power(lo, hi)
    n = max(table, key=lambda k: table[k])
    return table[n], n


def firing_fraction(p: int, bound: int) -> float:
    """Fraction of Hasse-window orders that die at smoothness bound `bound`."""
    lo, hi = hasse_window_bounds(p)
    table = segmented_max_prime_power(lo, hi)
    return sum(1 for v in table.values() if v <= bound) / len(table)


if __name__ == "__main__":
    for p in (19, 101, 401, 1601, 10007, 100003):
        b, n = wall_witness(p)
        lo, hi = hasse_window_bounds(p)
        print(f"p = {p:>7}  window [{lo},{hi}]  B*(p) = {b:>7}  attained at n = {n:>7}"
              f"  ratio {b / p:.3f}")
    assert wall(101) == 121          # 11^2, not the window's largest prime 113
    assert firing_fraction(101, 120) < 1.0 and firing_fraction(101, 121) == 1.0
    print("wall at p = 101 is 121 = 11^2, and it is a least element: verified")

