#!/usr/bin/env python3
"""Exact Fermat halting abscissa, gap, and pointwise fitted exponent.

For a semiprime N = p*q with p < q odd primes, Fermat's difference-of-squares search
halts at exactly x = (p+q)/2 and at no smaller abscissa (the only competing
representation, N = 1 * N, sits at the strictly larger x = (N+1)/2).  The work done is
therefore the walk from ceil(sqrt N) up to (p+q)/2, whose real-valued version is the
arithmetic-geometric defect

    G(p,q) = (p+q)/2 - sqrt(pq) = (sqrt q - sqrt p)^2 / 2.

This module evaluates the exact halting point by search (to certify the theorem
numerically), the gap in closed form, its q-derivative 1/2 - (1/2) sqrt(p/x), and the
pointwise fitted exponent log_p G.  The search costs G(p,q) + O(1) steps, i.e. Theta(p)
on a bounded-ratio arm; the closed forms are O(1).
"""

from __future__ import annotations

import math
from typing import Tuple


def fermat_halting_x(n: int) -> int:
    """Least x >= ceil(sqrt n) with x^2 - n a perfect square."""
    x = math.isqrt(n)
    if x * x < n:
        x += 1
    while True:
        d = x * x - n
        y = math.isqrt(d)
        if y * y == d:
            return x
        x += 1


def fermat_gap(p: float, q: float) -> float:
    """G(p,q) = (p+q)/2 - sqrt(pq), equal to (sqrt q - sqrt p)^2 / 2."""
    return (p + q) / 2.0 - math.sqrt(p * q)


def fermat_gap_derivative(p: float, q: float) -> float:
    """dG/dq = 1/2 - (1/2) sqrt(p/q); at least 0.14644 once q >= 2p."""
    return 0.5 - 0.5 * math.sqrt(p / q)


def fitted_exponent(p: int, q: int) -> float:
    """Pointwise fitted exponent log_p G(p,q)."""
    return math.log(fermat_gap(p, q), p)


def exact_exponent_on_double_arm(p: int) -> float:
    """On the arm q = 2p: exactly 1 + log(3/2 - sqrt 2)/log p, always below 1."""
    return 1.0 + math.log(1.5 - math.sqrt(2.0)) / math.log(p)


def scale_demanded(epsilon: float) -> Tuple[float, float]:
    """(minimum log p, minimum p) consistent with a fitted deficit <= epsilon."""
    need = -math.log(1.5 - math.sqrt(2.0)) / epsilon
    return need, math.exp(min(need, 700.0))


if __name__ == "__main__":
    for p, q in ((11, 23), (101, 211), (1009, 2027), (10007, 20011)):
        x = fermat_halting_x(p * q)
        assert x == (p + q) // 2, "Fermat must halt exactly at (p+q)/2"
        print(f"p = {p:>6}, q = {q:>6}:  halts at x = {x:>7} = (p+q)/2, "
              f"gap = {fermat_gap(p, q):>10.3f} = {fermat_gap(p, q) / p:.4f} p, "
              f"dG/dq = {fermat_gap_derivative(p, q):.4f}")
    print()
    for p in (101, 10 ** 3, 10 ** 6, 10 ** 12):
        print(f"p = {p:>13}:  log_p G(p,2p) = {exact_exponent_on_double_arm(p):.9f} "
              f"(always < 1)")
    need, _ = scale_demanded(1 - 0.9932)
    print(f"\na fitted exponent of 0.9932 requires log p >= {need:.1f}, "
          f"i.e. p >= 10^{need / math.log(10):.0f}")
